/// The messages of Bento's `message.proto` and `processor.proto`, generated by `build.rs`.
pub mod messagepb {
    include!(concat!(env!("OUT_DIR"), "/messagepb.rs"));
}

use csv::ReaderBuilder;
use messagepb::{part::Content, process_response::Result as Response, Batch, Error, Part, ProcessResponse};
use prost::Message;
use serde_json::{Map, Value};

/// Parses the CSV content of a message into JSON.
///
/// A message that can't be parsed is marked with its error, and continues
/// through the pipeline unchanged.
fn parse_csv(mut part: Part) -> Batch {
    let json = match &part.content {
        Some(Content::Raw(raw)) => csv_to_json(raw),
        _ => Err("expected raw content".to_string()),
    };
    match json {
        Ok(json) => part.content = Some(Content::Raw(json)),
        Err(e) => part.error = Some(Error { message: format!("CSV error: {}", e) }),
    }
    Batch { parts: vec![part] }
}

/// Converts CSV with a header row into a JSON array, with an object for each
/// record that maps each header to its value.
fn csv_to_json(csv_data: &[u8]) -> Result<Vec<u8>, String> {
    let mut rdr = ReaderBuilder::new()
        .has_headers(true)
        .from_reader(csv_data);

    let hdrs = rdr.headers()
        .map_err(|e| format!("Header error: {}", e))?
        .clone();

    let mut rows = Vec::new();
    for result in rdr.records() {
        let rec = result.map_err(|e| format!("Record error: {}", e))?;
        let mut obj = Map::new();
        for (i, header) in hdrs.iter().enumerate() {
            let val = rec.get(i).unwrap_or("");
            obj.insert(header.to_string(), Value::String(val.to_string()));
        }
        rows.push(Value::Object(obj));
    }

    serde_json::to_vec(&rows)
        .map_err(|e| format!("JSON error: {}", e))
}


//------------------------------------------------------------------------------
// The ABI, which resources/wasm/abi.wat defines.

#[cfg_attr(target_arch = "wasm32", export_name = "malloc")]
pub extern "C" fn _malloc(size: u32) -> *mut u8 {
    Box::into_raw(vec![0u8; size as usize].into_boxed_slice()) as *mut u8
}

#[cfg_attr(target_arch = "wasm32", export_name = "free")]
pub unsafe extern "C" fn _free(ptr: *mut u8, size: u32) {
    drop(Box::from_raw(std::ptr::slice_from_raw_parts_mut(ptr, size as usize)));
}

/// Returns the bytes of an input buffer, which Bento frees once the call
/// returns.
unsafe fn read<'a>(buffer: u64) -> &'a [u8] {
    let (ptr, len) = ((buffer >> 32) as *const u8, buffer as u32 as usize);
    if len == 0 {
        return &[];
    }
    std::slice::from_raw_parts(ptr, len)
}

/// Returns bytes as a buffer, which Bento frees with [`_free`].
fn write(bytes: Vec<u8>) -> u64 {
    if bytes.is_empty() {
        return 0;
    }
    let len = bytes.len() as u64;
    let ptr = Box::into_raw(bytes.into_boxed_slice()) as *mut u8 as u64;
    ptr << 32 | len
}

#[cfg_attr(target_arch = "wasm32", export_name = "process")]
pub unsafe extern "C" fn _process(part: u64) -> u64 {
    let result = match Part::decode(read(part)) {
        Ok(part) => Response::Batch(parse_csv(part)),
        Err(err) => Response::Error(Error { message: err.to_string() }),
    };
    write(ProcessResponse { result: Some(result) }.encode_to_vec())
}
